action.content:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const hash = value => crypto.createHash('sha256').update(value).digest('hex');
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-contract-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  return root;
}
function entry(file, value, mode = 0o644) {
  return { path: file, sha256: hash(value), size: Buffer.byteLength(value), mode };
}

test('verify sorts in JavaScript order and classifies every drift kind', t => {
  const root = fixture(t);
  fs.mkdirSync(path.join(root, 'dir'));
  fs.writeFileSync(path.join(root, 'dir', 'ok'), 'ok');
  fs.writeFileSync(path.join(root, 'content'), 'new');
  fs.writeFileSync(path.join(root, 'mode'), 'same'); fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.writeFileSync(path.join(root, 'both'), 'new'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.writeFileSync(path.join(root, 'final-dir'), ''); fs.mkdirSync(path.join(root, 'final-dir', 'child'));
  fs.mkdirSync(path.join(root, 'not-dir'));
  fs.symlinkSync('dir', path.join(root, 'link'));
  const manifest = { version: 1, files: [
    entry('z', 'z'), entry('content', 'old'), entry('mode', 'same'), entry('both', 'old'),
    entry('missing/child', 'x'), entry('link/ok', 'ok'), entry('not-dir/child', 'x'),
    entry('final-dir', ''), entry('dir/ok', 'ok'),
  ] };
  assert.deepEqual(verifyManifest(root, manifest), {
    ok: false, unchanged: ['dir/ok'],
    changed: [{ path: 'both', reasons: ['content', 'mode'] }, { path: 'content', reasons: ['content'] }, { path: 'mode', reasons: ['mode'] }],
    missing: ['missing/child', 'z'], unsafe: ['final-dir', 'link/ok', 'not-dir/child'],
  });
});

test('manifest validation is complete, non-mutating, and permits unknown fields', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a'), 'x');
  const manifest = { version: 1, ignored: true, files: [Object.assign(entry('a', 'x'), { extra: 1 })] };
  const before = JSON.stringify(manifest);
  assert.deepEqual(verifyManifest(root, manifest), { ok: true, unchanged: ['a'], changed: [], missing: [], unsafe: [] });
  assert.equal(JSON.stringify(manifest), before);
  assert.throws(() => verifyManifest(root, { version: 1, files: [entry('a', 'x'), { path: 'missing', sha256: 'BAD', size: 0, mode: 0 }] }));
  for (const bad of [null, [], {}, { version: 1, files: [{}] }, { version: 1, files: [entry('a', 'x'), entry('a', 'x')] }]) assert.throws(() => verifyManifest(root, bad));
  assert.deepEqual(verifyManifest(root, { version: 1, files: [] }), { ok: true, unchanged: [], changed: [], missing: [], unsafe: [] });
});

test('root and path symlinks are rejected, including trailing root separator', t => {
  const parent = fixture(t); const root = path.join(parent, 'root');
  fs.mkdirSync(root); fs.writeFileSync(path.join(root, 'file'), 'x');
  fs.symlinkSync(root, path.join(parent, 'root-link'));
  assert.throws(() => createManifest(`${path.join(parent, 'root-link')}/`, ['file']));
  fs.symlinkSync('file', path.join(root, 'file-link'));
  assert.deepEqual(verifyManifest(root, { version: 1, files: [entry('file-link', 'x')] }).unsafe, ['file-link']);
  for (const bad of ['', '/x', 'a//b', 'a/./b', 'a/../b', 'a\\b', 'a\0b']) assert.throws(() => createManifest(root, [bad]));
});

test('CLI creates, verifies, reports drift, and keeps import silent', t => {
  const root = fixture(t); const script = path.resolve('snapshot.js');
  fs.writeFileSync(path.join(root, 'a'), 'one');
  const created = spawnSync(process.execPath, [script, 'create', root, 'a'], { encoding: 'utf8' });
  assert.equal(created.status, 0); assert.equal(created.stderr, ''); assert.match(created.stdout, /\n$/);
  const manifestFile = path.join(root, 'manifest.json'); fs.writeFileSync(manifestFile, created.stdout);
  const verified = spawnSync(process.execPath, [script, 'verify', root, manifestFile], { encoding: 'utf8' });
  assert.equal(verified.status, 0); assert.equal(verified.stderr, ''); assert.deepEqual(JSON.parse(verified.stdout), { ok: true, unchanged: ['a'], changed: [], missing: [], unsafe: [] });
  fs.writeFileSync(path.join(root, 'a'), 'two');
  const drift = spawnSync(process.execPath, [script, 'verify', root, manifestFile], { encoding: 'utf8' });
  assert.equal(drift.status, 1); assert.equal(drift.stderr, ''); assert.deepEqual(JSON.parse(drift.stdout).changed, [{ path: 'a', reasons: ['content'] }]);
  const bad = spawnSync(process.execPath, [script, 'verify', root], { encoding: 'utf8' });
  assert.equal(bad.status, 2); assert.equal(bad.stdout, ''); assert.notEqual(bad.stderr, '');
  const imported = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(script)})`], { encoding: 'utf8' });
  assert.equal(imported.status, 0); assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
});

