  for (const name of ['z', 'ä', '雪']) { fs.writeFileSync(path.join(root, name), name); fs.chmodSync(path.join(root, name), 0o644); }
  const paths = Object.freeze(['雪', 'z', 'ä']);
  const manifest = createManifest(root, paths);
  assert.deepEqual(manifest.files.map(file => file.path), ['z', 'ä', '雪']);
  assert.deepEqual(paths, ['雪', 'z', 'ä']);
  Object.freeze(manifest.files); Object.freeze(manifest);
  assert.deepEqual(verifyManifest(root, manifest).unchanged, ['z', 'ä', '雪']);
  const good = entry('z', 'z');
  const badEntries = [
    null, [], 'entry', { ...good, path: 1 }, { ...good, path: 'a//b' }, { ...good, sha256: good.sha256 + '\n' },
    { ...good, sha256: good.sha256 + '\r' }, { ...good, sha256: 'A'.repeat(64) }, { ...good, size: -1 },
    { ...good, size: 1.5 }, { ...good, size: Number.MAX_SAFE_INTEGER + 1 }, { ...good, mode: -1 },
    { ...good, mode: 512 }, { ...good, mode: 1.5 }, { path: 'z', sha256: good.sha256, size: 1 },
  ];
  for (const bad of badEntries) assert.throws(() => verifyManifest(root, { version: 1, files: [bad] }));
});

test('root validation retains URL and Buffer roots without resolving invalid components', t => {
  const parent = fixture(t); const root = path.join(parent, 'root'); fs.mkdirSync(root);
  fs.writeFileSync(path.join(root, 'a'), 'a'); fs.chmodSync(path.join(root, 'a'), 0o644);
  assert.deepEqual(createManifest(new URL(`file://${root}`), ['a']).files, [entry('a', 'a')]);
  assert.deepEqual(createManifest(Buffer.from(root), ['a']).files, [entry('a', 'a')]);
  for (const bad of [`${parent}/missing/..`, `${root}/a/..`]) assert.throws(() => createManifest(bad, []));
  fs.symlinkSync(root, path.join(parent, 'link'));
  assert.throws(() => createManifest(`${path.join(parent, 'link')}/`, []));
});

test('dangling symlinks are unsafe and copied special-character CLI entrypoint executes', t => {
  const root = fixture(t); fs.symlinkSync('nowhere', path.join(root, 'dangling'));
  assert.deepEqual(verifyManifest(root, { version: 1, files: [entry('dangling', '')] }).unsafe, ['dangling']);
  const copied = path.join(root, 'copy # % space'); fs.mkdirSync(copied);
  const script = path.join(copied, 'snapshot.js'); fs.copyFileSync(path.resolve('snapshot.js'), script); fs.chmodSync(script, 0o644);
  fs.writeFileSync(path.join(root, 'a'), 'a'); fs.chmodSync(path.join(root, 'a'), 0o644);
  const result = spawnSync(process.execPath, [script, 'create', root, 'a'], { encoding: 'utf8' });
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.deepEqual(JSON.parse(result.stdout).files, [entry('a', 'a')]);
});

