test('POSIX root resolution preserves filesystem identity and literal backslashes', t => {
  if (process.platform !== 'linux' && process.platform !== 'darwin') t.skip('POSIX-only path semantics');
  const parent = fixture(t);
  const lexicalParent = path.join(parent, 'lexical-parent'); fs.mkdirSync(lexicalParent);
  const elsewhere = path.join(parent, 'elsewhere'); fs.mkdirSync(elsewhere);
  const nested = path.join(elsewhere, 'nested'); fs.mkdirSync(nested);
  fs.writeFileSync(path.join(elsewhere, 'selected'), 'elsewhere'); fs.chmodSync(path.join(elsewhere, 'selected'), 0o644);
  const link = path.join(parent, 'link'); fs.symlinkSync(nested, link);
  const manifest = createManifest(`${link}/..`, ['selected']);
  assert.deepEqual(manifest.files, [entry('selected', 'elsewhere')]);
  assert.deepEqual(verifyManifest(`${link}/..`, manifest), { ok: true, unchanged: ['selected'], changed: [], missing: [], unsafe: [] });
  const backslashRoot = path.join(parent, 'literal-backslash\\'); fs.mkdirSync(backslashRoot);
  fs.writeFileSync(path.join(backslashRoot, 'a'), 'a'); fs.chmodSync(path.join(backslashRoot, 'a'), 0o644);
  assert.deepEqual(createManifest(backslashRoot, ['a']).files, [entry('a', 'a')]);
  assert.deepEqual(createManifest('////', []), { version: 1, files: [] });
  assert.deepEqual(verifyManifest('////', { version: 1, files: [] }), { ok: true, unchanged: [], changed: [], missing: [], unsafe: [] });
});

