  fs.writeFileSync(path.join(root, 'content'), 'new'); fs.chmodSync(path.join(root, 'content'), 0o644);
  fs.writeFileSync(path.join(root, 'size-only'), 'same'); fs.chmodSync(path.join(root, 'size-only'), 0o644);
  fs.writeFileSync(path.join(root, 'mode'), 'same'); fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.writeFileSync(path.join(root, 'both'), 'new'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.mkdirSync(path.join(root, 'final-dir'));
  fs.writeFileSync(path.join(root, 'not-dir'), '');
  fs.symlinkSync('dir', path.join(root, 'link'));
