test('CLI creates, verifies, reports drift, and keeps import silent', t => {
  const root = fixture(t); const script = path.resolve('snapshot.js');
  fs.writeFileSync(path.join(root, 'a'), 'one'); fs.chmodSync(path.join(root, 'a'), 0o644);
  const created = spawnSync(process.execPath, [script, 'create', root, 'a'], { encoding: 'utf8' });
  assert.equal(created.status, 0); assert.equal(created.stderr, ''); assert.match(created.stdout, /\n$/);
  const manifestFile = path.join(root, 'manifest.json'); fs.writeFileSync(manifestFile, created.stdout); fs.chmodSync(manifestFile, 0o644);
  const verified = spawnSync(process.execPath, [script, 'verify', root, manifestFile], { encoding: 'utf8' });
  assert.equal(verified.status, 0); assert.equal(verified.stderr, ''); assert.deepEqual(JSON.parse(verified.stdout), { ok: true, unchanged: ['a'], changed: [], missing: [], unsafe: [] });
  fs.writeFileSync(path.join(root, 'a'), 'two'); fs.chmodSync(path.join(root, 'a'), 0o644);
  const drift = spawnSync(process.execPath, [script, 'verify', root, manifestFile], { encoding: 'utf8' });
  assert.equal(drift.status, 1); assert.equal(drift.stderr, ''); assert.deepEqual(JSON.parse(drift.stdout).changed, [{ path: 'a', reasons: ['content'] }]);
  for (const args of [['verify', root], ['verify', root, manifestFile, 'extra'], ['create'], ['wat'], ['create', root, '../bad']]) {
    const bad = spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
    assert.equal(bad.status, 2); assert.equal(bad.stdout, ''); assert.notEqual(bad.stderr, '');
  }
  fs.writeFileSync(path.join(root, 'bad.json'), '{'); fs.chmodSync(path.join(root, 'bad.json'), 0o644);
  fs.writeFileSync(path.join(root, 'bad-manifest.json'), JSON.stringify({ version: 2, files: [] })); fs.chmodSync(path.join(root, 'bad-manifest.json'), 0o644);
  fs.mkdirSync(path.join(root, 'unreadable.json'));
  for (const file of ['bad.json', 'bad-manifest.json', 'missing.json', 'unreadable.json']) {
    const bad = spawnSync(process.execPath, [script, 'verify', root, path.join(root, file)], { encoding: 'utf8' });
    assert.equal(bad.status, 2); assert.equal(bad.stdout, ''); assert.notEqual(bad.stderr, '');
  }
  const badRoot = spawnSync(process.execPath, [script, 'create', path.join(root, 'a')], { encoding: 'utf8' });
  assert.equal(badRoot.status, 2); assert.equal(badRoot.stdout, ''); assert.notEqual(badRoot.stderr, '');
  const imported = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(script)})`], { encoding: 'utf8' });
  assert.equal(imported.status, 0); assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
});

test('manifest validation rejects exact malformed fields and preserves frozen Unicode input ordering', t => {
  const root = fixture(t);
  for (const name of ['z', 'ä', '雪']) { fs.writeFileSync(path.join(root, name), name); fs.chmodSync(path.join(root, name), 0o644); }
  const paths = Object.freeze(['雪', 'z', 'ä']);
  const manifest = createManifest(root, paths);
  assert.deepEqual(manifest.files.map(file => file.path), ['z', 'ä', '雪']);
  assert.deepEqual(paths, ['雪', 'z', 'ä']);
  Object.freeze(manifest.files); Object.freeze(manifest);
  assert.deepEqual(verifyManifest(root, manifest).unchanged, ['z', 'ä', '雪']);
  const good = entry('z', 'z');
  const badEntries = [
    null, [], 'entry', { ...good, path: 1 }, { ...good, path: 'a//b' }, { ...good, sha256: good.sha256 + '\n' },
    { ...good, sha256: good.sha256 + '\r' }, { ...good, sha256: 'A'.repeat(64) }, { ...good, size: -1 },
    { ...good, size: 1.5 }, { ...good, size: Number.MAX_SAFE_INTEGER + 1 }, { ...good, mode: -1 },
    { ...good, mode: 512 }, { ...good, mode: 1.5 }, { path: 'z', sha256: good.sha256, size: 1 },
  ];
