  const lexicalParent = path.join(parent, 'lexical-parent'); fs.mkdirSync(lexicalParent);
  const elsewhere = path.join(parent, 'elsewhere'); fs.mkdirSync(elsewhere);
  const nested = path.join(elsewhere, 'nested'); fs.mkdirSync(nested);
  fs.writeFileSync(path.join(elsewhere, 'selected'), 'elsewhere'); fs.chmodSync(path.join(elsewhere, 'selected'), 0o644);
  const link = path.join(parent, 'link'); fs.symlinkSync(nested, link);
